insert into public.forum_posts (id, author_id, author_name, avatar, location, category, title, body, media_url, media_kind, like_count, created_at) values
  ('a2000000-0000-4000-8000-000000000021', null, 'Jasmine', '🌻', 'Ottawa, ON', 'milestone', '$30K down payment saved 🎉', 'Two years of automating every payday. The FHSA did most of the heavy lifting — the refund each spring went straight back in.', 'data:image/svg+xml;base64,', 'image', 33, now() - interval '5 days'),
  ('a2000000-0000-4000-8000-000000000022', null, 'Diego', '🧭', 'Winnipeg, MB', 'advice', 'How the FHSA + HBP actually stack (my real numbers)', 'FHSA: $40K contributed, ~$12K in refunds recycled. HBP on top: $35K from my RRSP. Combined that covered my whole down payment on a $410K condo. Ask me anything.', null, null, 41, now() - interval '8 days'),
  ('a2000000-0000-4000-8000-000000000023', null, 'Fatima', '🏡', 'Edmonton, AB', 'firsthome', 'We got the keys! 🔑', '18 months of following the plan in this app. Watching the date move earlier every time I logged a deposit kept me going. Still surreal.', 'data:image/svg+xml;base64,', 'image', 62, now() - interval '2 days'),
  ('a2000000-0000-4000-8000-000000000024', null, 'Ryan', '🦫', 'Hamilton, ON', 'question', 'Fixed vs variable for a first mortgage right now?', 'Getting close to pre-approval. Broker asked fixed or variable and I froze. What did other first-timers pick and would you do it again?', null, null, 9, now() - interval '1 days'),
  ('a2000000-0000-4000-8000-000000000025', null, 'Chloé', '🌷', 'Québec City, QC', 'milestone', 'The SOLD sign is up on OUR place', 'Offer accepted last night. Closing in 6 weeks. To everyone still saving: your date is real, keep logging those deposits.', 'data:image/svg+xml;base64,', 'image', 54, now() - interval '3 days'),
  ('a2000000-0000-4000-8000-000000000026', null, 'Amara', '⭐', 'Surrey, BC', 'advice', 'Co-buying with my sister — what we wish we knew', 'Get the co-ownership agreement drawn up by a lawyer BEFORE you buy. Who pays what, what happens if someone wants out. Awkward talk, saved us a huge headache.', null, null, 28, now() - interval '6 days')
insert into public.forum_replies (id, post_id, author_id, author_name, avatar, body, created_at) values
  ('b3000000-0000-4000-8000-000000000010', '11111111-1111-4111-8111-000000000001', null, 'Diego', '🧭', 'Congrats! Which bank did you use for the FHSA?', now() - interval '3 days'),
  ('b3000000-0000-4000-8000-000000000011', '11111111-1111-4111-8111-000000000001', null, 'Jasmine', '🌻', 'This is so motivating, thank you for sharing 🙌', now() - interval '2 days'),
  ('b3000000-0000-4000-8000-000000000012', '11111111-1111-4111-8111-000000000002', null, 'Ryan', '🦫', '25% is huge. How long did that take you?', now() - interval '4 days'),
  ('b3000000-0000-4000-8000-000000000013', '11111111-1111-4111-8111-000000000003', null, 'Fatima', '🏡', 'The HBP repayment schedule tripped me up at first — worth reading the lesson twice.', now() - interval '5 days'),
  ('b3000000-0000-4000-8000-000000000014', '11111111-1111-4111-8111-000000000004', null, 'Amara', '⭐', 'Ours ran about 2.1% of the price all-in. Budget for the land transfer tax!', now() - interval '2 days'),
  ('b3000000-0000-4000-8000-000000000015', '11111111-1111-4111-8111-000000000005', null, 'Chloé', '🌷', 'Huge congrats 🎉 what neighbourhood?', now() - interval '1 days')
